using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "The science of numbers, quantity, and space." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." },
            new() { Id = 6, Name = "Biology", Code = "BIO", Description = "The study of living organisms and life processes." }
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, Title = "Introduction to Programming", CourseCode = "CS101",
                Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen",
                InstructorBio = "Dr. Chen holds a PhD in Computer Science from MIT and has 15 years of experience teaching introductory programming. Her research focuses on CS education and accessible computing.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 2, Title = "Data Structures and Algorithms", CourseCode = "CS201",
                Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Dr. James Park",
                InstructorBio = "Dr. Park is an expert in algorithm optimization with publications in ACM and IEEE conferences. He previously worked at Google Research before joining academia.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 3, Title = "Database Systems", CourseCode = "CS340",
                Description = "Covers relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases and distributed data systems.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Gonzalez",
                InstructorBio = "Dr. Gonzalez spent a decade in industry at Oracle and Amazon before transitioning to academia. She specializes in distributed databases and query optimization.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false
            },
            new()
            {
                Id = 4, Title = "Calculus I", CourseCode = "MATH101",
                Description = "Introduction to differential calculus covering limits, continuity, derivatives, and their applications. Includes related rates, optimization, and curve sketching.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Turing Jr.",
                InstructorBio = "Dr. Turing Jr. is passionate about making calculus accessible. He has authored two best-selling calculus textbooks and received multiple teaching excellence awards.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true
            },
            new()
            {
                Id = 5, Title = "Linear Algebra", CourseCode = "MATH220",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of linear equations.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Priya Sharma",
                InstructorBio = "Dr. Sharma's research spans numerical linear algebra and machine learning theory. She collaborates with the CS department on interdisciplinary AI projects.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
            },
            new()
            {
                Id = 6, Title = "General Physics I", CourseCode = "PHYS101",
                Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments in kinematics, Newton's laws, energy conservation, and oscillations.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", InstructorName = "Dr. Richard Feynman II",
                InstructorBio = "Dr. Feynman II brings physics to life with dynamic demonstrations and real-world applications. His YouTube channel on physics education has over 500K subscribers.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true
            },
            new()
            {
                Id = 7, Title = "Quantum Mechanics", CourseCode = "PHYS401",
                Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum states, operators, angular momentum, and applications to atomic and molecular systems.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Lisa Randall",
                InstructorBio = "Dr. Randall is a theoretical physicist whose work on extra dimensions has been widely cited. She bridges complex quantum concepts with intuitive explanations.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false
            },
            new()
            {
                Id = 8, Title = "English Composition", CourseCode = "ENG101",
                Description = "Develops skills in academic writing including thesis development, argumentation, research methods, proper citation, and revision strategies.",
                Credits = 3, Schedule = "Mon/Wed 9:00–10:20 AM", InstructorName = "Prof. Elizabeth Warren",
                InstructorBio = "Prof. Warren is a published author and writing coach with 20 years of experience helping students find their academic voice. She specializes in rhetoric and composition pedagogy.",
                DepartmentId = 4, DepartmentName = "English", IsFeatured = false
            },
            new()
            {
                Id = 9, Title = "World History to 1500", CourseCode = "HIST101",
                Description = "Survey of major civilizations, cultural exchanges, and transformative events from antiquity through the late medieval period across Africa, Asia, Europe, and the Americas.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Kevin Zhang",
                InstructorBio = "Dr. Zhang specializes in comparative world history and has conducted archaeological fieldwork in China and Central Asia. He emphasizes primary source analysis in his teaching.",
                DepartmentId = 5, DepartmentName = "History", IsFeatured = false
            },
            new()
            {
                Id = 10, Title = "Molecular Biology", CourseCode = "BIO301",
                Description = "Study of biological processes at the molecular level including DNA replication, transcription, translation, gene regulation, and modern techniques in molecular biology.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Tue 3:00–5:50 PM", InstructorName = "Dr. Angela Brooks",
                InstructorBio = "Dr. Brooks runs an active research lab focused on RNA splicing and gene therapy. Her students regularly publish in peer-reviewed journals alongside her.",
                DepartmentId = 6, DepartmentName = "Biology", IsFeatured = true
            }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses() => _courses;

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database.
        return true;
    }
}

